import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
exp_path = os.path.join(working_dir, "experiment_data.npy")
experiment_data = np.load(exp_path, allow_pickle=True).item()

for dataset_name, data in experiment_data.items():
    print(f"\n=== Dataset: {dataset_name} ===")

    auroc_per_variant = data.get("auroc_per_variant", {})
    auroc_folds = data.get("auroc_folds", {})

    for variant, auroc in auroc_per_variant.items():
        print(f"{variant} mean 5-fold CV AUROC: {auroc:.4f}")
        if variant in auroc_folds:
            folds = auroc_folds[variant]
            print(f"{variant} std 5-fold CV AUROC: {np.std(folds):.4f}")

    group_aggs = ["mean_pool", "max_pool", "concat"]
    per_agent = ["agent1", "agent2", "agent3"]

    group_results = {
        k: auroc_per_variant[k] for k in group_aggs if k in auroc_per_variant
    }
    agent_results = {
        k: auroc_per_variant[k] for k in per_agent if k in auroc_per_variant
    }

    if group_results:
        best_group = max(group_results, key=group_results.get)
        print(f"Best group-aggregated variant: {best_group}")
        print(f"Best group-aggregated AUROC: {group_results[best_group]:.4f}")

    if agent_results:
        best_agent = max(agent_results, key=agent_results.get)
        print(f"Best per-agent variant: {best_agent}")
        print(f"Best per-agent AUROC: {agent_results[best_agent]:.4f}")

    if "tfidf_text" in auroc_per_variant:
        print(f"TF-IDF text-only AUROC: {auroc_per_variant['tfidf_text']:.4f}")

    if "random_features" in auroc_per_variant:
        print(
            f"Random features control AUROC: {auroc_per_variant['random_features']:.4f}"
        )

    if "collusion_detection_auroc" in data:
        print(
            f"Collusion detection AUROC (final): {data['collusion_detection_auroc']:.4f}"
        )
